[
 {
  "id": "M1",
  "name": "Independent completion standard authored before implementation (the instrument)",
  "factory": {
   "description": "A validator surveys a reference program, maps where its behavior lives, and builds a weighted body of cases plus comparison rules before any implementation. Byte identity on exit code, stdout, stderr, and full work-tree delta is the default; relaxations exist only as named normalizers attached to specific cases, each carrying a recorded licence. The implementation is then held to that standard.",
   "evidence": "factory-large-tasks, the whole article; the published gdal grading policy; the frontier data (median 64.65 -> 90.10, median delta +23.5, zero regressions, computed by me from the page's own per-task tooltips).",
   "limits": "ProgramBench supplies an oracle binary, which is what makes an instrument constructible; Factory says other tasks 'draw their standard from different sources' but demonstrates none of them. No independent measure of instrument quality. No ablation isolating the instrument from the other two roles. One run per cell, no variance estimate."
  },
  "dsh": {
   "status": "partial",
   "packages": [
    "@deepseek-ai/dsh-verification",
    "@deepseek-ai/dsh-environment-runner",
    "@deepseek-ai/dsh-environments"
   ],
   "notes": "As a durable contract ours is stronger: author-before-implementation, append-only extend, relax only with recorded unsatisfiability evidence, a verification/run for every executed run passing or failing, a certificate only from a fully passing run, and an ./invariant companion that rejects a certificate no fully passing run of the same revision precedes. As an instrument-construction mechanism ours is absent: the runner transcribes pre-declared environment checks verbatim; nothing surveys a reference to derive what to measure (W2 stage 4 Validator is proposed).",
   "verdict": "stronger"
  }
 },
 {
  "id": "M2",
  "name": "Role separation: orchestrator, implementer, validator",
  "factory": {
   "description": "Three roles with one goal each. The orchestrator plans, adjudicates findings, issues directives and decides when to ship; the implementer builds; the validator measures. Rationale is that an append-only trajectory biases a self-reviewing agent toward confirming what it already did.",
   "evidence": "factory-large-tasks (the outer loop); factory-missions-arch (the trajectory-coherence argument); factory-model-routing ('our default validator comes from a different model family than our default implementer').",
   "limits": "In the ProgramBench experiment all three roles used the same model at the same reasoning level, so role separation there is context separation, not model diversity. No ablation separates the orchestrator's contribution from the validator's."
  },
  "dsh": {
   "status": "partial",
   "packages": [
    "@deepseek-ai/dsh-subagent",
    "@deepseek-ai/dsh-subagent-acp",
    "@deepseek-ai/dsh-subagent-codex",
    "@deepseek-ai/dsh-subagent-claude-code",
    "@deepseek-ai/dsh-subagent-dsh-sdk",
    "@deepseek-ai/dsh-environment-runner"
   ],
   "notes": "Seven subagent providers including four out-of-process ones give broader provider heterogeneity than Factory documents, and our validator half is a deterministic executor rather than an LLM. But the shipped three-role composition does not exist: orchestrator and review-council roles are proposed (W1 stage 10, W2 stage 9).",
   "verdict": "weaker"
  }
 },
 {
  "id": "M3",
  "name": "The wall: information barrier around the measurement sample",
  "factory": {
   "description": "The implementer never authors, runs, or sees the instrument's cases or raw output; only clustered feature-level directives cross. The validator may expand the instrument but may not weaken or revise it to fit the candidate.",
   "evidence": "factory-large-tasks, the wall section, plus the published gdal directive showing weights and area names but no cases.",
   "limits": "The sources describe the wall as an architectural property and never describe an enforcement mechanism. Where the instrument's files live relative to the implementer's workspace, whether the implementer has a shell that could read them, and what happens if it does, are all unstated. No tamper detection is described. The one-directional rule is stated as a rule with no described gate that refuses a weakening edit."
  },
  "dsh": {
   "status": "partial",
   "packages": [
    "@deepseek-ai/dsh-read-barrier",
    "@deepseek-ai/dsh-fs-read-barrier",
    "@deepseek-ai/dsh-tools",
    "@deepseek-ai/dsh-agent-presets",
    "@deepseek-ai/dsh-verification"
   ],
   "notes": "Slices 1-4 landed: a validator-owned 0700 root with reserve/protect/resolve/denies; fs/read-intent as a delegating waterfall with FS_READ_BARRIER_DENIED enforced in dsh-tool-fs and dsh-tool-str-replace-editor; ToolAuthority on ToolDefinition with a mountPreset audit and a monotonic ctx.tools.guard(); a durable read-barrier/scope census cross-checked against every request/header; VerificationCertificate.executor; and isolationProblem() refusing process/host for an agent-reported run or an unenforced capability, applied identically live and on replay. Slice 5 (shell/subprocess/terminal denial) and slice 6 (tamper) have NOT landed, so a shell-capable implementer reaches the standard today.",
   "verdict": "stronger"
  }
 },
 {
  "id": "M4",
  "name": "Validation contract authored before feature decomposition",
  "factory": {
   "description": "At mission level the orchestrator writes a finite checklist of testable behavioral assertions before decomposing into features; each feature claims which assertions it fulfils; features group into milestones.",
   "evidence": "factory-missions-arch: 'the orchestrator defines correctness first... before defining any features. This ordering matters.'",
   "limits": "The contract is authored by the same orchestrator that later adjudicates findings. Assertions are natural language plus evidence hints, not executable checks. Nothing described prevents reinterpretation at validation time."
  },
  "dsh": {
   "status": "proposed",
   "packages": [],
   "notes": "W2 stage 5's Plan derived from compiled standards and the ProgramLedger are proposed in .agents/notes/proposed/architecture/2026-09-05-four-goal-workflows.md; no package exists. dsh-plan-mode is per-agent logged plan state, not a multi-goal contract.",
   "verdict": "weaker"
  }
 }
]
--- M18/M19 ---
[
 {
  "id": "M18",
  "name": "Failure clustering into non-leaking directives",
  "factory": {
   "description": "The validator groups failures by root cause; the orchestrator rejects noise or invalid measurements and turns the rest into a directive at the level of missing features, subsystems or behavior - naming areas and weights without revealing cases.",
   "evidence": "factory-large-tasks, the wall section, and the published gdal directive fragment with per-area case-mass weights.",
   "limits": "How clustering is done, and how the orchestrator decides a finding is 'noise or an invalid measurement', are unstated. That adjudication is the point where a standard could quietly collapse, and no gate is described."
  },
  "dsh": {
   "status": "partial",
   "packages": [
    "@deepseek-ai/dsh-verification",
    "@deepseek-ai/dsh-environment-runner"
   ],
   "notes": "The no-leak property is already enforced: the runner's directive detail carries the failing evidence and never a check id, outcome, or command. But there is no clustering: rootCause is a count of failing checks and detail is bounded raw evidence, so the implementer gets noise where Factory's gets a weighted map of weak areas.",
   "verdict": "weaker"
  }
 },
 {
  "id": "M19",
  "name": "RL data export from certified trajectories",
  "factory": {
   "description": "Not present in any Factory source read. Factory is a product company; nothing in its published material describes exporting session trajectories as training data.",
   "evidence": "absence across all 21 sources read",
   "limits": "Absence of evidence only; Factory may do this privately."
  },
  "dsh": {
   "status": "landed",
   "packages": [
    "@deepseek-ai/dsh-trajectories",
    "@deepseek-ai/dsh-environments",
    "@deepseek-ai/dsh-scorekeeper"
   ],
   "notes": "dsh-trajectory/1 JSONL records fold persisted sessions into chat-format messages whose reward a certificate decided, carrying the environment/run stamp; held-out sessions are withheld by that stamp unless explicitly requested, configured districts are withheld by default, and every withheld session is counted rather than silently dropped. What is missing is the tamper reward basis (needs read-barrier slice 6) and the outcome: null masking for truncated, aborted and provider-error sessions.",
   "verdict": "stronger"
  }
 }
]

