// Build baselines.html from factory-analysis.json and ai-village-docs.json.
// Status values are overridden below where the research files predate the branch head
// (ef4e07906): dsh-shifts slices 1-2, read-barrier slice 6, and the scorekeeper cost fold.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = dirname(fileURLToPath(import.meta.url))
const read = (n) => JSON.parse(readFileSync(join(dir, n), 'utf8'))
const FA = read('factory-analysis.json')
const AV = read('ai-village-docs.json')
const HEAD = 'ef4e07906'
const DATE = '2026-09-06'

const fm = Object.fromEntries(FA.mechanisms.map(m => [m.id, m]))
const vm = Object.fromEntries(AV.mechanisms.map(m => [m.id, m]))

// ---------------------------------------------------------------- frontier pairs
const frontierClaim = FA.sources.find(s => s.id === 'factory-large-tasks').claims.find(c => c.startsWith('DATA'))
const PAIRS = [...frontierClaim.matchAll(/([a-z0-9-]+)\s(\d+\.\d)->(\d+\.\d)/g)]
  .map(([, task, a, b]) => ({ task, single: Number(a), system: Number(b) }))
const median = (xs) => { const s = [...xs].sort((x, y) => x - y); const h = s.length / 2; return s.length % 2 ? s[Math.floor(h)] : (s[h - 1] + s[h]) / 2 }
const STATS = {
  n: PAIRS.length,
  medSingle: median(PAIRS.map(p => p.single)).toFixed(2),
  medSystem: median(PAIRS.map(p => p.system)).toFixed(2),
  medDelta: median(PAIRS.map(p => p.system - p.single)).toFixed(2),
  minDelta: Math.min(...PAIRS.map(p => p.system - p.single)).toFixed(1),
  maxDelta: Math.max(...PAIRS.map(p => p.system - p.single)).toFixed(1),
  regressions: PAIRS.filter(p => p.system < p.single).length,
}

// ---------------------------------------------------------------- mechanism matrix
// Every Factory id M1-M19 and every Village id M1-M16 appears exactly once.
const ROWS = [
  { label: 'Completion standard authored before implementation', f: ['M1'], v: ['M5'], status: 'partial', verdict: 'stronger as a durable standard, absent as an instrument builder' },
  { label: 'Role separation: orchestrator, implementer, validator', f: ['M2'], v: [], status: 'partial', verdict: 'weaker as a shipped composition, stronger on provider heterogeneity' },
  { label: 'Information barrier around the measurement sample', f: ['M3'], v: [], status: 'partial', verdict: 'stronger in kind, bounded in coverage' },
  { label: 'Validation contract before feature decomposition', f: ['M4'], v: [], status: 'proposed', verdict: 'weaker' },
  { label: 'Tests before code plus black-box user-level validation', f: ['M5'], v: [], status: 'partial', verdict: 'weaker' },
  { label: 'Fresh workspace and context per unit of work', f: ['M6'], v: ['M1'], status: 'landed', verdict: 'stronger for measurement, weaker for real-world agency' },
  { label: 'Memory and compaction across sessions', f: ['M7', 'M10'], v: ['M4'], status: 'partial', verdict: 'stronger on integrity, weaker on longitudinal persistence' },
  { label: 'Probe-based evaluation of compaction quality', f: ['M8'], v: [], status: 'absent', verdict: 'weaker, and cheap to close' },
  { label: 'Deferred tool and capability schemas', f: ['M9'], v: [], status: 'partial', verdict: 'weaker for tools, equal for skills' },
  { label: 'Tool repertoire, authority and environment design', f: ['M11'], v: ['M2'], status: 'landed', verdict: 'equal in design discipline, stronger on authority' },
  { label: 'Graded autonomy, sandboxing and moderation', f: ['M12'], v: ['M12'], status: 'partial', verdict: 'stronger on enforcement primitives, weaker on the operator ladder' },
  { label: 'Human steering and attributed approval', f: [], v: ['M6'], status: 'partial', verdict: 'stronger on enforcement, weaker on attribution' },
  { label: 'Specification mode before implementation', f: ['M13'], v: [], status: 'partial', verdict: 'weaker as a shipped workflow' },
  { label: 'Parallel fan-out and headless execution', f: ['M14'], v: [], status: 'landed', verdict: 'stronger for evaluation fan-out, weaker for a feature-parallel runner' },
  { label: 'Model routing and priced cost accounting', f: ['M15'], v: ['M10'], status: 'partial', verdict: 'stronger on cost as durable evidence, weaker on routing' },
  { label: 'Evaluation methodology and comparison discipline', f: ['M16'], v: ['M8'], status: 'landed', verdict: 'stronger by construction, unproven in public' },
  { label: 'Harness variant as a measured arm', f: [], v: ['M9'], status: 'partial', verdict: 'equal: neither side can attribute a row to a harness version today' },
  { label: 'Enterprise controls, analytics and attribution', f: ['M17'], v: [], status: 'proposed', verdict: 'weaker' },
  { label: 'Failure clustering into non-leaking directives', f: ['M18'], v: [], status: 'partial', verdict: 'weaker' },
  { label: 'Training-data export from certified runs', f: ['M19'], v: ['M11'], status: 'landed', verdict: 'stronger on derivation and withholding, weaker on publication' },
  { label: 'Outcome measurement against self-report', f: [], v: ['M13'], status: 'landed', verdict: 'stronger, decisively' },
  { label: 'Outreach to real people under approval', f: [], v: ['M7'], status: 'partial', verdict: 'stronger today by abstention, weaker the moment we want agency' },
  { label: 'Inter-agent communication', f: [], v: ['M3'], status: 'absent', verdict: 'weaker on multi-agent dynamics, stronger on contamination control' },
  { label: 'Emergent institutions and a promotion path', f: [], v: ['M14'], status: 'proposed', verdict: 'weaker in practice, stronger in design' },
  { label: 'Orchestration, restart and supervision', f: [], v: ['M15'], status: 'partial', verdict: 'weaker for always-on, and closing' },
  { label: 'A public always-on format', f: [], v: ['M16'], status: 'absent', verdict: 'weaker' },
]

// Status and note overrides for what landed after the research files were written.
const HEAD_NOTE = {
  'Information barrier around the measurement sample': 'Read-barrier slices 1-4 and 6 are landed at head: the validator-owned 0700 root, FS_READ_BARRIER_DENIED at the filesystem executor, tool authority with a monotonic guard, the certificate executor, and tamper verdicts with the read-barrier-tamper fixture and snapshot. Slice 5 leaves shell, subprocess and terminal open, so a shell-capable composition still cannot claim process isolation.',
  'Model routing and priced cost accounting': 'Landed at head: budget-policy records usage/priced per priced step with both rates and a pricing-table digest, and the scorekeeper folds pricedSteps, costEur, pricingDigests and costEurPerCertified. No router exists.',
  'Orchestration, restart and supervision': 'Landed at head as shifts slices 1-2: the shift digest, the shift ledger events, resume by ledger and stamp scan, cadence, the spend window, the invariant companion, and the observe-only fleet cell event. Scorekeeper shift rows and the supervision gate message remain.',
  'Training-data export from certified runs': 'Landed at head: trajectory records whose reward a certificate decided, with the tamper reward basis, held-out and district withholding by the stamp, and every withheld session counted. Redaction, consent and residency are proposed.',
  'Evaluation methodology and comparison discipline': 'Landed at head, with the district column now part of the scoreboard key the leaderboard refuses to average across. An experiment arm is still a model route, not a preset.',
  'Harness variant as a measured arm': 'Composition-manifest slice 1 is landed at head: component digests and content addressing. The manifest event, preset-as-arm and the leaderboard harness-variant id are proposed.',
}
const PKGS = {
  'Completion standard authored before implementation': ['dsh-verification', 'dsh-environment-runner', 'dsh-environments'],
  'Role separation: orchestrator, implementer, validator': ['dsh-subagent', 'dsh-environment-runner'],
  'Information barrier around the measurement sample': ['dsh-read-barrier', 'dsh-fs-read-barrier', 'dsh-verification'],
  'Validation contract before feature decomposition': [],
  'Tests before code plus black-box user-level validation': ['dsh-environment-runner', 'dsh-verification'],
  'Fresh workspace and context per unit of work': ['dsh-fleet', 'dsh-environment-runner', 'dsh-tool-ralph'],
  'Memory and compaction across sessions': ['dsh-compaction-basic', 'dsh-compaction-tool-result-pruner', 'dsh-skill'],
  'Probe-based evaluation of compaction quality': ['dsh-experiments'],
  'Deferred tool and capability schemas': ['dsh-skill', 'dsh-tool-skill'],
  'Tool repertoire, authority and environment design': ['dsh-tools', 'dsh-timeout-policy', 'dsh-repeat-tool-reminder'],
  'Graded autonomy, sandboxing and moderation': ['dsh-sandbox-local', 'dsh-sandbox-policy', 'dsh-tools'],
  'Human steering and attributed approval': ['dsh-user-approval', 'dsh-budget-policy'],
  'Specification mode before implementation': ['dsh-plan-mode'],
  'Parallel fan-out and headless execution': ['dsh-fleet', 'dsh-subagent', 'dsh-workflow'],
  'Model routing and priced cost accounting': ['dsh-budget-policy', 'dsh-scorekeeper'],
  'Evaluation methodology and comparison discipline': ['dsh-experiments', 'dsh-fleet', 'dsh-scorekeeper'],
  'Harness variant as a measured arm': ['dsh-components', 'dsh-experiments'],
  'Enterprise controls, analytics and attribution': ['dsh-identity', 'dsh-credentials', 'dsh-settings'],
  'Failure clustering into non-leaking directives': ['dsh-verification', 'dsh-environment-runner'],
  'Training-data export from certified runs': ['dsh-trajectories', 'dsh-scorekeeper'],
  'Outcome measurement against self-report': ['dsh-verification', 'dsh-environment-runner', 'dsh-scorekeeper'],
  'Outreach to real people under approval': ['verify-village-composition', 'dsh-read-barrier'],
  'Inter-agent communication': [],
  'Emergent institutions and a promotion path': ['dsh-skill', 'dsh-components'],
  'Orchestration, restart and supervision': ['dsh-shifts', 'dsh-fleet', 'dsh-session-checkpoint-policy'],
  'A public always-on format': [],
}

const matrix = ROWS.map(r => ({
  label: r.label,
  ids: [...r.f.map(i => `F-${i}`), ...r.v.map(i => `V-${i}`)],
  factory: r.f.map(i => fm[i].factory.description).join(' ') || 'No counterpart in the Factory sources read.',
  factoryLimit: r.f.map(i => fm[i].factory.limits).join(' '),
  village: r.v.map(i => vm[i].village.description).join(' ') || 'No counterpart in the Village record.',
  villageLacks: r.v.map(i => vm[i].village.lacks).join(' '),
  status: r.status,
  packages: PKGS[r.label],
  daliesk: HEAD_NOTE[r.label] ?? [...r.f.map(i => fm[i].dsh.notes), ...r.v.map(i => vm[i].dsh.notes)].join(' '),
  verdict: r.verdict,
}))

// ---------------------------------------------------------------- Village operating numbers
const OPERATING = [
  ['2025-04-02', 'First shift', 'Four agents, one open-ended goal, two hours a weekday.'],
  ['2025-07-18', 'Three hours a day', 'Seven agents; the human chat closes later in the same phase.'],
  ['2025-10-22', 'Four to five hours a day', 'Ten or eleven agents through the end of 2025.'],
  ['2026-02-02', '16 goals, 19 models in 2025', '$2,000 raised for charity, a 23-person live event, $200 of merchandise revenue, 39 research participants.'],
  ['2026-06-29', 'Eight hours a day, 9am to 5pm Pacific', 'The current schedule; the FAQ answer for live hours was silently edited after this change.'],
  ['2026-06-16', 'On the order of $10k per month', 'The single public cost figure in seventeen months, stated as an estimate.'],
  ['2026-08-25', '16 chat-only agents introduced', 'A second class of agent identities, all still active.'],
  ['2026-08-28', '$12.6M grant, four technical staff', 'A philanthropic award to a nonprofit, not a funding round.'],
  ['2026-09-06', '46 computer-agent records, 32 active', '48 live agent identities against the 27 the hiring post states.'],
]

// ---------------------------------------------------------------- roadmap
const ROADMAP = [
  { slice: 'Read-barrier slice 5: process-level denial', pkg: 'read-barrier, sandbox-local, sandbox-policy', status: 'in progress', note: 'Unblocks the hidden-checks claim and every isolation claim above none. Slices 1-4 and 6 are landed.' },
  { slice: 'The instrument: comparator and named normalizers on StandardCheck', pkg: 'verification, environment-runner, agent-presets', status: 'proposed', note: 'A validator-role preset and a check-authoring tool over the completion-standard service.' },
  { slice: 'Failure clustering into an area-and-weight directive', pkg: 'environment-runner', status: 'proposed', note: 'Keeps the no-leak property the runner already has.' },
  { slice: 'Recreation environments with two separate metrics', pkg: 'environments, scorekeeper', status: 'proposed', note: 'Percent resolved and raw pass rate ship as separate fields or neither renders.' },
  { slice: 'The program ledger', pkg: 'program (new), goal, verification', status: 'proposed', note: 'Durable program events mapping each goal to its session, workspace, preset, isolation, budget and status.' },
  { slice: 'Composition-manifest slice 2 and onward', pkg: 'components-*, scorekeeper, trajectories', status: 'proposed', note: 'Slice 1 is landed. The manifest writer is what makes preset-as-arm and the harness-variant claim possible.' },
  { slice: 'Status page that is current or visibly stale', pkg: 'observatory', status: 'proposed', note: 'Renders the newest folded session timestamp and replaces the numbers past a staleness threshold.' },
  { slice: 'Agent-instability protocol between continue and stop', pkg: 'shifts', status: 'proposed', note: 'Parks a route with a durable reason and requires an attributed decision to resume.' },
  { slice: 'Serious-incident channel separate from publication', pkg: 'governance', status: 'proposed', note: 'A logged, routed path with a named recipient and a time bound, drilled before the first public shift.' },
  { slice: 'Probe-based compaction evaluation and deferred tool schemas', pkg: 'experiments, tools, interaction', status: 'proposed', note: 'Cost and quality wins off the critical path to a defensible published number.' },
  { slice: 'Shift ledger, resume, cadence and spend window', pkg: 'shifts', status: 'landed', note: 'Slices 1-2 at head, with the observe-only fleet cell event.' },
  { slice: 'Tamper verdicts and the tamper reward basis', pkg: 'environments, environment-runner, verification, trajectories', status: 'landed', note: 'Read-barrier slice 6, with the read-barrier-tamper fixture and snapshot.' },
  { slice: 'Cost per certified session folded from priced usage', pkg: 'budget-policy, scorekeeper', status: 'landed', note: 'Priced steps, cost, pricing digests and cost per certified session, with the district column.' },
]

// ---------------------------------------------------------------- html
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const DATA = { head: HEAD, date: DATE, pairs: PAIRS, stats: STATS, matrix, operating: OPERATING, roadmap: ROADMAP, failures: AV.failures, claims: AV.claims_gated, never: FA.never_claim }

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Daliesk Baselines</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&family=Inter:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root {
  color-scheme: light;
  --paper: #f6f4ef;
  --card: #fffefb;
  --ink: #1c1a17;
  --ink-2: #4c4740;
  --ink-3: #7b7469;
  --rule: #ded8cc;
  --rule-2: #ebe6dc;
  --accent: #8a3a1e;
  --accent-soft: #f0e2d9;
  --landed: #1f6b52;
  --landed-bg: #dfeee7;
  --partial: #8a6410;
  --partial-bg: #f3e8ce;
  --proposed: #2b5680;
  --proposed-bg: #dde7f1;
  --absent: #6a635a;
  --absent-bg: #e7e2d8;
  --single: #9a938a;
  --system: #8a3a1e;
  --mark: #fbf0c9;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --paper: #17161a;
    --card: #1e1d22;
    --ink: #eae7e1;
    --ink-2: #b3ada4;
    --ink-3: #8b857c;
    --rule: #34323a;
    --rule-2: #2a282f;
    --accent: #e08d5f;
    --accent-soft: #33251d;
    --landed: #6fc4a2;
    --landed-bg: #17332a;
    --partial: #d7ab54;
    --partial-bg: #33290f;
    --proposed: #7fadd8;
    --proposed-bg: #17263a;
    --absent: #9b948a;
    --absent-bg: #2a282f;
    --single: #6f6a63;
    --system: #e08d5f;
    --mark: #3b3316;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --paper: #17161a;
  --card: #1e1d22;
  --ink: #eae7e1;
  --ink-2: #b3ada4;
  --ink-3: #8b857c;
  --rule: #34323a;
  --rule-2: #2a282f;
  --accent: #e08d5f;
  --accent-soft: #33251d;
  --landed: #6fc4a2;
  --landed-bg: #17332a;
  --partial: #d7ab54;
  --partial-bg: #33290f;
  --proposed: #7fadd8;
  --proposed-bg: #17263a;
  --absent: #9b948a;
  --absent-bg: #2a282f;
  --single: #6f6a63;
  --system: #e08d5f;
  --mark: #3b3316;
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 400 15px/1.55 Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  overflow-x: hidden;
}
.wrap { max-width: 1180px; margin: 0 auto; padding: 0 22px 90px; }
h1, h2, h3 { font-family: "Source Serif 4", Georgia, "Times New Roman", serif; font-weight: 600; letter-spacing: -0.01em; }
a { color: var(--accent); text-underline-offset: 2px; }
code, .num, .mono { font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace; font-variant-numeric: tabular-nums; }
.num { font-variant-numeric: tabular-nums lining-nums; }

/* masthead */
header.mast { border-bottom: 2px solid var(--ink); margin: 0 0 34px; padding: 30px 0 14px; }
.mast-top { display: flex; flex-wrap: wrap; gap: 14px; align-items: baseline; justify-content: space-between; }
.mast h1 { margin: 0; font-size: clamp(28px, 4.4vw, 42px); line-height: 1.08; }
.mast .kicker { font: 500 11px/1 "IBM Plex Mono", monospace; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-3); margin: 0 0 10px; }
.mast .standfirst { max-width: 62ch; color: var(--ink-2); margin: 14px 0 0; font-size: 16px; }
.provenance { display: flex; flex-wrap: wrap; gap: 6px 26px; margin: 18px 0 0; padding: 0; list-style: none; font-size: 12.5px; color: var(--ink-3); }
.provenance b { color: var(--ink-2); font-weight: 500; }
button.theme {
  font: 500 12px/1 "IBM Plex Mono", monospace; letter-spacing: 0.06em; text-transform: uppercase;
  background: transparent; color: var(--ink-2); border: 1px solid var(--rule); border-radius: 3px;
  padding: 7px 11px; cursor: pointer;
}
button.theme:hover { border-color: var(--ink-3); color: var(--ink); }

/* sections */
section { margin: 0 0 56px; scroll-margin-top: 16px; }
.sec-head { display: flex; align-items: baseline; gap: 14px; border-bottom: 1px solid var(--rule); padding-bottom: 8px; margin-bottom: 18px; }
.sec-head h2 { margin: 0; font-size: 22px; }
.sec-head .idx { font: 500 12px/1 "IBM Plex Mono", monospace; color: var(--accent); letter-spacing: 0.1em; }
.sec-head .note { margin-left: auto; font-size: 12.5px; color: var(--ink-3); }
.lede { max-width: 74ch; color: var(--ink-2); margin: 0 0 18px; }

nav.toc { position: sticky; top: 0; z-index: 5; background: var(--paper); border-bottom: 1px solid var(--rule); padding: 9px 0; margin-bottom: 26px; }
nav.toc ul { display: flex; flex-wrap: wrap; gap: 4px 18px; margin: 0; padding: 0; list-style: none; }
nav.toc a { font: 500 12px/1 "IBM Plex Mono", monospace; color: var(--ink-3); text-decoration: none; letter-spacing: 0.03em; }
nav.toc a:hover { color: var(--accent); }

/* chips */
.chip {
  display: inline-block; font: 500 11px/1 "IBM Plex Mono", monospace; letter-spacing: 0.07em;
  text-transform: uppercase; padding: 4px 7px; border-radius: 2px; white-space: nowrap;
}
.chip.landed { color: var(--landed); background: var(--landed-bg); }
.chip.partial { color: var(--partial); background: var(--partial-bg); }
.chip.proposed { color: var(--proposed); background: var(--proposed-bg); }
.chip.absent { color: var(--absent); background: var(--absent-bg); }
.chip[data-s="in progress"] { color: var(--partial); background: var(--partial-bg); }
.idtag { font: 400 11px/1 "IBM Plex Mono", monospace; color: var(--ink-3); }

/* controls */
.controls { display: flex; flex-wrap: wrap; gap: 10px 16px; align-items: center; margin: 0 0 14px; }
.controls input[type="search"] {
  flex: 1 1 240px; min-width: 180px; font: 400 14px Inter, sans-serif; color: var(--ink);
  background: var(--card); border: 1px solid var(--rule); border-radius: 3px; padding: 8px 11px;
}
.controls input[type="search"]:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
.filters { display: flex; flex-wrap: wrap; gap: 6px; }
.filters button {
  font: 500 11px/1 "IBM Plex Mono", monospace; letter-spacing: 0.07em; text-transform: uppercase;
  padding: 6px 9px; border-radius: 2px; border: 1px solid var(--rule); background: transparent;
  color: var(--ink-3); cursor: pointer;
}
.filters button[aria-pressed="true"] { border-color: currentColor; }
.filters button.landed[aria-pressed="true"] { color: var(--landed); background: var(--landed-bg); }
.filters button.partial[aria-pressed="true"] { color: var(--partial); background: var(--partial-bg); }
.filters button.proposed[aria-pressed="true"] { color: var(--proposed); background: var(--proposed-bg); }
.filters button.absent[aria-pressed="true"] { color: var(--absent); background: var(--absent-bg); }
.count { font: 400 12.5px "IBM Plex Mono", monospace; color: var(--ink-3); }

/* tables */
.scroll { overflow-x: auto; border: 1px solid var(--rule); border-radius: 4px; background: var(--card); }
table { border-collapse: collapse; width: 100%; font-size: 13.5px; }
thead th {
  text-align: left; font: 500 11px/1.3 "IBM Plex Mono", monospace; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--ink-3); padding: 11px 14px; border-bottom: 1px solid var(--rule);
  background: var(--card); vertical-align: bottom; position: sticky; top: 0;
}
tbody td { padding: 13px 14px; border-bottom: 1px solid var(--rule-2); vertical-align: top; color: var(--ink-2); }
tbody tr:last-child td { border-bottom: 0; }
tbody tr:hover td { background: color-mix(in srgb, var(--accent) 4%, transparent); }
td.mech { color: var(--ink); }
td.mech .m-label { font-weight: 600; display: block; margin-bottom: 6px; }
td.mech .verdict { display: block; margin-top: 8px; font-size: 12.5px; color: var(--ink-3); font-style: italic; }
.limits { display: block; margin-top: 7px; font-size: 12.5px; color: var(--ink-3); }
.limits::before { content: "Gap: "; font-family: "IBM Plex Mono", monospace; font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; }
.pkgs { display: block; margin-top: 8px; font-family: "IBM Plex Mono", monospace; font-size: 11.5px; color: var(--ink-3); word-break: break-word; }
#matrix table { min-width: 980px; }
#failures table { min-width: 820px; }
#claims table { min-width: 720px; }
#roadmap table { min-width: 760px; }
tr.claimable td { background: var(--mark); }
tr.claimable td:first-child { box-shadow: inset 3px 0 0 var(--accent); }
tr.claimable .claim-t { color: var(--ink); font-weight: 600; }

/* numbers panel */
.numbers { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr); gap: 24px; align-items: start; }
@media (max-width: 860px) { .numbers { grid-template-columns: 1fr; } }
.panel { border: 1px solid var(--rule); border-radius: 4px; background: var(--card); padding: 18px; }
.panel h3 { margin: 0 0 4px; font-size: 16px; }
.panel .sub { font-size: 12.5px; color: var(--ink-3); margin: 0 0 14px; }
.chart-legend { display: flex; gap: 18px; font-size: 12px; color: var(--ink-3); margin: 0 0 10px; }
.chart-legend i { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; vertical-align: -1px; }
svg.dumbbell { width: 100%; height: auto; display: block; }
svg.dumbbell text { font-family: "IBM Plex Mono", monospace; font-size: 9.5px; fill: var(--ink-3); }
svg.dumbbell text.task { fill: var(--ink-2); }
svg.dumbbell .grid { stroke: var(--rule-2); stroke-width: 1; }
svg.dumbbell .link { stroke: var(--rule); stroke-width: 5; stroke-linecap: round; }
.statgrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; background: var(--rule-2); border: 1px solid var(--rule-2); margin: 0 0 16px; }
.statgrid div { background: var(--card); padding: 11px 12px; }
.statgrid dt { font: 500 10.5px/1.3 "IBM Plex Mono", monospace; letter-spacing: 0.07em; text-transform: uppercase; color: var(--ink-3); margin: 0 0 5px; }
.statgrid dd { margin: 0; font-family: "IBM Plex Mono", monospace; font-variant-numeric: tabular-nums; font-size: 19px; color: var(--ink); }
.caveat { border-left: 3px solid var(--accent); padding: 2px 0 2px 13px; margin: 0 0 14px; font-size: 13.5px; color: var(--ink-2); }
.caveat strong { color: var(--ink); }
ol.timeline { list-style: none; margin: 0; padding: 0; }
ol.timeline li { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--rule-2); }
ol.timeline li:last-child { border-bottom: 0; }
ol.timeline time { font-family: "IBM Plex Mono", monospace; font-size: 12px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
ol.timeline b { display: block; font-weight: 600; color: var(--ink); font-size: 13.5px; }
ol.timeline span { font-size: 12.5px; color: var(--ink-2); }

ol.never { columns: 2; column-gap: 30px; margin: 0; padding: 0 0 0 20px; font-size: 13.5px; color: var(--ink-2); }
@media (max-width: 720px) { ol.never { columns: 1; } }
ol.never li { break-inside: avoid; margin: 0 0 9px; padding-left: 3px; }

footer { border-top: 1px solid var(--rule); padding-top: 16px; font-size: 12.5px; color: var(--ink-3); }
footer p { max-width: 76ch; }
.empty { padding: 22px 14px; color: var(--ink-3); font-size: 13.5px; }
</style>
</head>
<body>
<div class="wrap">

<header class="mast">
  <div class="mast-top">
    <div>
      <p class="kicker">Competitive baselines &middot; internal evidence record</p>
      <h1>Two baselines, measured against what our code can prove</h1>
    </div>
    <button class="theme" id="theme" type="button">Theme</button>
  </div>
  <p class="standfirst">Factory's validation-first system and the AI Village are the closest commercial and public precedents to the Daliesk seams. This page holds what each has actually demonstrated, what our packages can prove at branch head, and which public claims are unlocked today.</p>
  <ul class="provenance">
    <li><b>Head</b> <span class="mono">${HEAD}</span></li>
    <li><b>Compiled</b> <span class="mono">${DATE}</span></li>
    <li><b>Sources</b> <span class="num">${FA.sources.length}</span> Factory-side, <span class="num">${AV.sources.length}</span> Village-side</li>
    <li><b>Mechanisms</b> <span class="num">${FA.mechanisms.length}</span> + <span class="num">${AV.mechanisms.length}</span>, merged into <span class="num">${ROWS.length}</span> rows</li>
  </ul>
</header>

<nav class="toc" aria-label="Sections">
  <ul>
    <li><a href="#matrix">01 Mechanism matrix</a></li>
    <li><a href="#numbers">02 The numbers</a></li>
    <li><a href="#failures">03 Failure taxonomy</a></li>
    <li><a href="#claims">04 Gated claims</a></li>
    <li><a href="#roadmap">05 Parity slices</a></li>
  </ul>
</nav>

<section id="matrix">
  <div class="sec-head"><span class="idx">01</span><h2>Mechanism matrix</h2><span class="note">status verified against tracked source at head</span></div>
  <p class="lede">Every mechanism from both research passes appears exactly once, merged where the two describe the same thing. <em>Landed</em> means the code exists at head; <em>partial</em> means named slices remain; <em>proposed</em> means an Agent Note designs it and no package exists; <em>absent</em> means no design. The verdict compares what each side can prove, not what each side does.</p>
  <div class="controls">
    <input type="search" id="q" placeholder="Search mechanisms, packages, evidence&hellip;" aria-label="Search the matrix">
    <div class="filters" id="filters" role="group" aria-label="Filter by Daliesk status"></div>
    <span class="count" id="count"></span>
  </div>
  <div class="scroll">
    <table>
      <thead><tr><th style="width:22%">Mechanism</th><th style="width:26%">Factory</th><th style="width:26%">AI Village</th><th style="width:26%">Daliesk at head</th></tr></thead>
      <tbody id="matrix-body"></tbody>
    </table>
  </div>
</section>

<section id="numbers">
  <div class="sec-head"><span class="idx">02</span><h2>The numbers, with what they do and do not license</h2><span class="note">read from primary payloads, not from a summary</span></div>
  <div class="numbers">
    <div class="panel">
      <h3>Frontier pairs, best single agent against best system</h3>
      <p class="sub">All <span class="num">${STATS.n}</span> tasks, read from the article figure's own tooltips. Ordered by the single-agent value.</p>
      <div class="chart-legend"><span><i style="background:var(--single)"></i>best single agent</span><span><i style="background:var(--system)"></i>best system</span></div>
      <div id="chart"></div>
    </div>
    <div>
      <div class="panel" style="margin-bottom:24px">
        <h3>What the pairs say</h3>
        <p class="sub">Medians and deltas computed from the same 24 rows.</p>
        <dl class="statgrid">
          <div><dt>Median, single agent</dt><dd class="num">${STATS.medSingle}</dd></div>
          <div><dt>Median, system</dt><dd class="num">${STATS.medSystem}</dd></div>
          <div><dt>Median delta</dt><dd class="num">+${STATS.medDelta}</dd></div>
          <div><dt>Regressions</dt><dd class="num">${STATS.regressions}</dd></div>
        </dl>
        <p class="caveat"><strong>One run per cell.</strong> No variance estimate anywhere, the 24 tasks were hand-picked from the benchmark's hardest end, and the campaigns were not compute-matched. Deltas range from +${STATS.minDelta} to +${STATS.maxDelta}.</p>
        <p class="caveat"><strong>Raw pass rate is not percent resolved.</strong> The benchmark's primary metric is the fraction of tasks where every test passes, and no model in its paper baselines resolved a single one. These numbers are the raw fraction of hidden-suite checks passed. Quoting one beside the other misrepresents both.</p>
        <p class="caveat"><strong>The cost was not the constraint.</strong> System runs on one task took 14 times the credits and 13 times the wall time, and every single-agent campaign ended when the agent decided it was done.</p>
      </div>
      <div class="panel">
        <h3>Village operating record</h3>
        <p class="sub">Dated facts from the Village's own posts and site.</p>
        <ol class="timeline">${OPERATING.map(([d, t, s]) => `<li><time>${esc(d)}</time><div><b>${esc(t)}</b><span>${esc(s)}</span></div></li>`).join('')}</ol>
      </div>
    </div>
  </div>
</section>

<section id="failures">
  <div class="sec-head"><span class="idx">03</span><h2>Failure taxonomy, and our counterpart for each class</h2><span class="note">${AV.failures.length} classes from the Village's own writing</span></div>
  <p class="lede">Each class is drawn from what the Village published about itself. The counterpart column states what our code does about it and, where it does nothing, says so.</p>
  <div class="scroll">
    <table>
      <thead><tr><th style="width:22%">Failure class</th><th style="width:26%">Numbers</th><th style="width:24%">Their response</th><th style="width:28%">Our counterpart</th></tr></thead>
      <tbody>${AV.failures.map(f => `<tr><td class="mech"><span class="m-label">${esc(f.class.replace(/-/g, ' ').replace(/^./, c => c.toUpperCase()))}</span></td><td>${esc(f.numbers)}</td><td>${esc(f.response)}</td><td>${esc(f.dsh_counterpart)}</td></tr>`).join('')}</tbody>
    </table>
  </div>
</section>

<section id="claims">
  <div class="sec-head"><span class="idx">04</span><h2>Gated claims</h2><span class="note">one row is claimable today</span></div>
  <p class="lede">Every claim we might want to make in public, and the exact evidence that unlocks it. The highlighted row is the only one landed evidence already supports.</p>
  <div class="scroll">
    <table>
      <thead><tr><th style="width:40%">Claim</th><th style="width:60%">Unlocked by</th></tr></thead>
      <tbody>${AV.claims_gated.map((c) => {
        const [claim, ...rest] = c.split(/\s+-\s+/)
        const gate = rest.join(' - ')
        const claimable = /CLAIMABLE NOW/.test(gate)
        return `<tr class="${claimable ? 'claimable' : ''}"><td class="claim-t">${esc(claim)}</td><td>${esc(gate)}</td></tr>`
      }).join('')}</tbody>
    </table>
  </div>
  <div class="panel" style="margin-top:24px">
    <h3>Thirteen rules that hold without exception</h3>
    <p class="sub">A claim on this list is never made, whatever the pressure to make it.</p>
    <ol class="never">${FA.never_claim.map(r => `<li>${esc(r)}</li>`).join('')}</ol>
  </div>
</section>

<section id="roadmap">
  <div class="sec-head"><span class="idx">05</span><h2>Parity slices and today's status</h2><span class="note">ordered by what blocks the next public claim</span></div>
  <p class="lede">Each slice names the package it lands in. Three are landed at head; one is in progress in another worktree; the rest are designed and unbuilt.</p>
  <div class="scroll">
    <table>
      <thead><tr><th style="width:30%">Slice</th><th style="width:20%">Package</th><th style="width:12%">Status</th><th style="width:38%">What it unblocks</th></tr></thead>
      <tbody>${ROADMAP.map(r => `<tr><td class="mech"><span class="m-label">${esc(r.slice)}</span></td><td class="pkgs" style="margin:0">${esc(r.pkg)}</td><td><span class="chip ${r.status === 'in progress' ? 'partial' : r.status}" data-s="${esc(r.status)}">${esc(r.status)}</span></td><td>${esc(r.note)}</td></tr>`).join('')}</tbody>
    </table>
  </div>
</section>

<footer>
  <p>Compiled from two primary-source research passes: <span class="mono">factory-analysis.json</span> (${FA.sources.length} sources, ${FA.mechanisms.length} mechanisms) and <span class="mono">ai-village-docs.json</span> (${AV.sources.length} sources, ${AV.mechanisms.length} mechanisms, ${AV.failures.length} failure classes). Every figure here traces to one of those two files; nothing on this page came from a summarizing tool. Status columns were re-verified against tracked source at <span class="mono">${HEAD}</span> rather than taken from either research file's wording.</p>
</footer>

</div>
<script>
const DATA = ${JSON.stringify(DATA).replace(/</g, '\\u003c')};

/* theme */
(function () {
  const root = document.documentElement;
  let stored = null;
  try { stored = localStorage.getItem('daliesk-baselines-theme'); } catch (e) { /* private mode: fall back to system */ }
  if (stored === 'light' || stored === 'dark') root.setAttribute('data-theme', stored);
  document.getElementById('theme').addEventListener('click', function () {
    const isDark = root.getAttribute('data-theme') === 'dark'
      || (!root.hasAttribute('data-theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    const next = isDark ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    try { localStorage.setItem('daliesk-baselines-theme', next); } catch (e) { /* private mode: theme is per-view */ }
    drawChart();
  });
})();

/* matrix */
const STATUSES = ['landed', 'partial', 'proposed', 'absent'];
const active = new Set(STATUSES);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const filtersEl = document.getElementById('filters');
filtersEl.innerHTML = STATUSES.map(s =>
  '<button type="button" class="' + s + '" data-s="' + s + '" aria-pressed="true">' + s +
  ' <span class="num">' + DATA.matrix.filter(r => r.status === s).length + '</span></button>').join('');
filtersEl.addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b) return;
  const s = b.dataset.s;
  if (active.has(s)) active.delete(s); else active.add(s);
  b.setAttribute('aria-pressed', active.has(s) ? 'true' : 'false');
  render();
});
const q = document.getElementById('q');
q.addEventListener('input', render);

function render() {
  const term = q.value.trim().toLowerCase();
  const rows = DATA.matrix.filter(r => {
    if (!active.has(r.status)) return false;
    if (!term) return true;
    return [r.label, r.factory, r.factoryLimit, r.village, r.villageLacks, r.daliesk, r.verdict, r.ids.join(' '), (r.packages || []).join(' ')]
      .join(' ').toLowerCase().includes(term);
  });
  const body = document.getElementById('matrix-body');
  body.innerHTML = rows.length ? rows.map(r =>
    '<tr>' +
    '<td class="mech"><span class="m-label">' + esc(r.label) + '</span>' +
      '<span class="idtag">' + esc(r.ids.join(' \\u00b7 ')) + '</span>' +
      '<span class="verdict">' + esc(r.verdict) + '</span></td>' +
    '<td>' + esc(r.factory) + (r.factoryLimit ? '<span class="limits">' + esc(r.factoryLimit) + '</span>' : '') + '</td>' +
    '<td>' + esc(r.village) + (r.villageLacks ? '<span class="limits">' + esc(r.villageLacks) + '</span>' : '') + '</td>' +
    '<td><span class="chip ' + r.status + '">' + r.status + '</span> ' + esc(r.daliesk) +
      ((r.packages && r.packages.length) ? '<span class="pkgs">' + esc(r.packages.join('  ')) + '</span>' : '') + '</td>' +
    '</tr>').join('') : '<tr><td colspan="4" class="empty">No mechanism matches that filter.</td></tr>';
  document.getElementById('count').textContent = rows.length + ' of ' + DATA.matrix.length + ' shown';
}
render();

/* dumbbell chart */
function drawChart() {
  const host = document.getElementById('chart');
  const pairs = DATA.pairs.slice().sort((a, b) => a.single - b.single);
  const rowH = 19, padT = 22, padB = 6, padL = 74, padR = 34;
  const W = 640, H = padT + pairs.length * rowH + padB;
  const x = v => padL + (v / 100) * (W - padL - padR);
  const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  const single = css('--single'), system = css('--system');
  let s = '<svg class="dumbbell" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Per-task parity, best single agent against best system">';
  for (let g = 0; g <= 100; g += 25) {
    s += '<line class="grid" x1="' + x(g) + '" y1="' + (padT - 8) + '" x2="' + x(g) + '" y2="' + (H - padB) + '"/>';
    s += '<text x="' + x(g) + '" y="' + (padT - 12) + '" text-anchor="middle">' + g + '</text>';
  }
  pairs.forEach((p, i) => {
    const y = padT + i * rowH + rowH / 2;
    s += '<text class="task" x="' + (padL - 9) + '" y="' + (y + 3.2) + '" text-anchor="end">' + p.task + '</text>';
    s += '<line class="link" x1="' + x(p.single) + '" y1="' + y + '" x2="' + x(p.system) + '" y2="' + y + '"/>';
    s += '<circle cx="' + x(p.single) + '" cy="' + y + '" r="3.6" fill="' + single + '"><title>' + p.task + ' single agent ' + p.single + '</title></circle>';
    s += '<circle cx="' + x(p.system) + '" cy="' + y + '" r="3.6" fill="' + system + '"><title>' + p.task + ' system ' + p.system + '</title></circle>';
    s += '<text x="' + (x(p.system) + 7) + '" y="' + (y + 3.2) + '">' + p.system.toFixed(1) + '</text>';
  });
  host.innerHTML = s + '</svg>';
}
drawChart();
</script>
</body>
</html>
`

