// -------------------------------------------------------- number provenance check
const corpus = ['factory-analysis.md', 'factory-analysis.json', 'ai-village-docs.md', 'ai-village-docs.json']
  .map(f => readFileSync(join(dir, f), 'utf8')).join('\n')
const ALLOW = new Set([HEAD, '01', '02', '03', '04', '05', '4'])
const pageText = [
  ...matrix.flatMap(r => [r.label, r.factory, r.factoryLimit, r.village, r.villageLacks, r.daliesk, r.verdict, r.ids.join(' '), (r.packages || []).join(' ')]),
