  ...AV.failures.flatMap(f => [f.class, f.numbers, f.response, f.dsh_counterpart]),
  ...AV.claims_gated, ...FA.never_claim,
  ...PAIRS.flatMap(p => [p.task, String(p.single), String(p.system)]),
  ...Object.values(STATS).map(String),
  `Head ${HEAD} Compiled ${DATE} Sources ${FA.sources.length} Factory-side ${AV.sources.length} Village-side`,
  `Mechanisms ${FA.mechanisms.length} + ${AV.mechanisms.length} merged into ${ROWS.length} rows`,
  `All ${STATS.n} tasks. Deltas range from +${STATS.minDelta} to +${STATS.maxDelta}. 14 times the credits and 13 times the wall time.`,
  `${AV.failures.length} classes from the Village's own writing. Thirteen rules that hold without exception.`,
].join('\n')

const tokens = [...new Set((pageText.match(/\d[\d.,]*/g) || []).map(t => t.replace(/[.,]$/, '')))]
const missing = tokens.filter(t => !ALLOW.has(t) && !corpus.includes(t))
console.log(`baselines.html written: ${PAIRS.length} pairs, ${matrix.length} mechanism rows, ${AV.failures.length} failure classes, ${AV.claims_gated.length} gated claims, ${ROADMAP.length} roadmap slices`)
console.log(`number provenance: ${tokens.length} distinct numeric tokens on the page, ${missing.length} not found in the research corpus${missing.length ? ': ' + missing.join(', ') : ''}`)

// Validate baselines.html: read it, extract the inline script, and syntax-check it with node --check.
import { readFileSync, writeFileSync, unlinkSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = dirname(fileURLToPath(import.meta.url))
const html = readFileSync(join(dir, 'baselines.html'), 'utf8')

const fail = (m) => { console.error('FAIL ' + m); process.exitCode = 1 }
const ok = (m) => console.log('OK   ' + m)

// Structure.
if (!/^<!doctype html>/i.test(html)) fail('no doctype'); else ok('doctype present')
const title = html.match(/<title>([^<]*)<\/title>/)
if (!title || title[1] !== 'Daliesk Baselines') fail('title is not "Daliesk Baselines"')
else ok('title is "Daliesk Baselines"')

// Balanced tags for the elements that carry the layout.
for (const tag of ['html', 'head', 'body', 'style', 'script', 'table', 'section', 'svg']) {
  const open = (html.match(new RegExp('<' + tag + '(?=[\\s>])', 'g')) || []).length
  const close = (html.match(new RegExp('</' + tag + '>', 'g')) || []).length
  if (open !== close) fail(`<${tag}> ${open} open vs ${close} close`)
}
ok('open and close tag counts match for html, head, body, style, script, table, section, svg')

// Only Google Fonts may be external.
const external = [...html.matchAll(/(?:href|src)="(https?:\/\/[^"]+)"/g)].map(m => m[1])
const bad = external.filter(u => !/^https:\/\/fonts\.(googleapis|gstatic)\.com\//.test(u))
if (bad.length) fail('non-Google-Fonts external resources: ' + bad.join(', ')); else ok(`${external.length} external references, all Google Fonts`)

// Theming and layout requirements.
for (const [needle, what] of [
  ['@media (prefers-color-scheme: dark)', 'prefers-color-scheme dark block'],
  [':root:not([data-theme="light"])', 'system-dark guard'],
  [':root[data-theme="dark"]', 'explicit dark override'],
  ['background: var(--paper)', 'explicit body background'],
  ['overflow-x: hidden', 'page-level horizontal scroll suppressed'],
  ['.scroll { overflow-x: auto', 'tables in an overflow-x auto container'],
]) if (!html.includes(needle)) fail('missing ' + what); else ok('has ' + what)

const tables = (html.match(/<table>/g) || []).length
const scrolls = (html.match(/<div class="scroll">/g) || []).length
if (tables !== scrolls) fail(`${tables} tables but ${scrolls} scroll containers`)
else ok(`all ${tables} tables sit in an overflow-x container`)

// The inline script must parse.
const script = html.match(/<script>([\s\S]*?)<\/script>/)
if (!script) { fail('no inline script found'); process.exit(1) }
const tmp = join(dir, '.baselines-script.check.js')
writeFileSync(tmp, script[1])
try {
  execFileSync(process.execPath, ['--check', tmp], { stdio: 'pipe' })
  ok(`inline script parses (${script[1].length} bytes) under node --check`)
} catch (err) {
  fail('inline script does not parse: ' + String(err.stderr || err.message))
} finally {
  unlinkSync(tmp)
}

// The embedded data must be valid JSON.
const data = script[1].match(/^const DATA = (\{[\s\S]*?\});$/m)
if (!data) fail('embedded DATA object not found')
else {
  try {
    const parsed = JSON.parse(data[1].replace(/\\u003c/g, '<'))
    ok(`embedded DATA parses: ${parsed.matrix.length} mechanism rows, ${parsed.pairs.length} pairs, ${parsed.failures.length} failure classes, ${parsed.claims.length} gated claims, ${parsed.never.length} never-claim rules, ${parsed.roadmap.length} roadmap slices`)
  } catch (err) { fail('embedded DATA is not valid JSON: ' + err.message) }
}

console.log(process.exitCode ? 'baselines-check: FAILED' : 'baselines-check: all checks passed')

